class Person {
    String name;
    Person(String n) { name = n; }
    String describe() { return "Person: " + name; }
}
class Student extends Person {
    int grade;
    Student(String n, int g) { super(n); grade = g; }
    @Override String describe() { return super.describe() + ", Grade: " + grade; }
}
System.out.println(new Student("Ana", 10).describe());
